mapper.select:
SELECT COUNT(1) > 0
FROM op_user
WHERE USER_ID = #{email}

mapper.update:
UPDATE op_user
SET PUSH_TOKEN  = #{pushToken}
   ,DEVICE_TYPE = #{deviceType}
WHERE USER_NO   = #{userNo}

mapper.select:
SELECT USER_ID, MEMBER_CODE, PUSH_TOKEN, DEVICE_TYPE
FROM op_user
WHERE USER_ID = #{userId}

SELECT USER_ID, MEMBER_CODE, PUSH_TOKEN, DEVICE_TYPE, USER_NO
FROM op_user
WHERE USER_NO = #{userNo}

SELECT A.EMAIL
FROM op_user A
WHERE A.CTTPC   = #{cttpc}
AND   A.USER_NM = #{userNm}
LIMIT 1

SELECT USER_ID, SELECTOR, VERIFIER_HASH, EXPIRES_AT, USED_YN
FROM tb_password_reset
WHERE USER_ID = #{userId}
AND USED_YN = 'N'
AND EXPIRES_AT > #{now}
LIMIT 1

mapper.update:
UPDATE tb_password_reset
SET USED_YN = 'Y'
WHERE USER_ID = #{userId}

UPDATE op_user
SET PASSWORD = #{member_new_pw}
   ,UPDT_DT  = CURRENT_TIMESTAMP
WHERE user_ID= #{member_id}

UPDATE tb_social_account
SET LAST_LOGIN_AT = CURRENT_TIMESTAMP
WHERE PROVIDER = #{provider}
  AND PROVIDER_USER_ID = #{providerUserId}

mapper.select:
SELECT COUNT(1) > 0
FROM tb_social_account
WHERE   PROVIDER        = #{provider}
AND     PROVIDER_USER_ID= #{providerUserId}

mapper.delete:
DELETE FROM tb_social_account
WHERE PROVIDER = #{provider}
  AND PROVIDER_USER_ID = #{providerUserId}

mapper.select:
SELECT USER_NO, USER_ID, DEVICE_TYPE, PUSH_TOKEN
FROM op_user
WHERE BRANCH_ID = #{branchId}
  AND MEMBER_CODE = #{memberCode}
  AND USER_STTUS_CODE = '10'
